{
  "schema_version": 1,
  "engine_version": "1.0.0",
  "rules": [
    {
      "id": "sensitive-file-write",
      "version": 1,
      "severity": "high",
      "tags": [
        "file",
        "sensitive",
        "write"
      ],
      "source": "file",
      "description": "Detect writes to sensitive paths outside package management",
      "condition": {
        "and": [
          {
            "field": "file.path",
            "operator": "starts_with",
            "value": "/etc"
          },
          {
            "not": {
              "field": "process.exec_path",
              "operator": "in",
              "value": [
                "/usr/bin/dpkg",
                "/usr/bin/rpm"
              ]
            }
          }
        ]
      },
      "action": "alert",
      "exceptions": [
        {
          "field": "process.exec_path",
          "operator": "ends_with",
          "value": "/ansible-playbook"
        }
      ],
      "lists": [
        {
          "name": "sensitive_paths",
          "items": [
            "/etc/shadow",
            "/etc/passwd",
            "/etc/sudoers"
          ]
        }
      ],
      "sequences": [
        {
          "name": "exec_then_connect",
          "steps": [
            {
              "field": "process.exec_path",
              "operator": "eq",
              "value": "/bin/sh"
            },
            {
              "field": "network.dst_port",
              "operator": "in",
              "value": [
                4444,
                5555
              ]
            }
          ],
          "window_seconds": 60
        }
      ]
    },
    {
      "id": "deny-protected-keys",
      "version": 1,
      "severity": "critical",
      "tags": [
        "file",
        "deny"
      ],
      "source": "file",
      "description": "Deny mutation of secure-boot keys on authoritative kernel facts",
      "condition": {
        "field": "file.path",
        "operator": "eq",
        "value": "/etc/secure-boot/keys"
      },
      "action": "deny",
      "exceptions": [],
      "lists": [],
      "sequences": []
    }
  ]
}
